/**
 * Fetch Epics To Input Pre-CLI Action
 * Fetches existing epics and writes them to the input folder before CLI agent runs.
 * Receives params.inputFolderPath from DMTools after input folder creation.
 */

/**
 * Pre-CLI action: fetch existing epics into input folder
 *
 * @param {Object} params - Parameters from DMTools
 * @param {string} params.inputFolderPath - Path to the input folder for this run
 */

// Load-time require (gh-823): a deferred require would resolve against the
// pack js/ root only — hoist every require to the top of the module.
var trackersModule = require("./common/trackers.js");

/**
 * Find a field value by partial key name (handles "Display Name (customfieldXXX)" keys).
 */
function findField(fields, nameSubstring) {
    for (var key in fields) {
        if (key.indexOf(nameSubstring) !== -1) {
            return fields[key];
        }
    }
    return null;
}

function action(params) {
    try {
        const folder = params.inputFolderPath;
        var ticketKey = folder ? folder.split('/').pop() : '';
        var project = ticketKey ? ticketKey.split('-')[0] : '';
        var tracker = trackersModule.createTracker(null, (params.jobParams && params.jobParams.customParams) || params.customParams || {});
        console.log('Fetching existing epics for project ' + project + '...');

        try {
            var rawEpics = tracker.searchIssues(
                // JQL text: provider-specific query (WIQL on ado)
                'project = ' + project + ' AND issuetype = Epic ORDER BY created DESC', {
                fields: ['key', 'summary', 'description', 'priority', 'parent']
            });
            var epics = [];
            for (var i = 0; i < rawEpics.length; i++) {
                try {
                    var issue = tracker.getIssue(rawEpics[i].key);
                    var f = issue.fields || {};
                    epics.push({
                        key: issue.key || '',
                        summary: f.summary || '',
                        description: f.description || '',
                        priority: f.priority ? f.priority.name : '',
                        diagrams: f['Diagrams (customfield_10296)'] || f.Diagrams || null,
                        parent: f.parent ? f.parent.key : null
                    });
                } catch (e) {
                    console.error('Failed to fetch epic ' + rawEpics[i].key + ':', e);
                }
            }
            console.log('Found ' + epics.length + ' epics');
            file_write(folder + '/existing_epics.json', '{"epics":' + JSON.stringify(epics, null, 2) + '}');
            console.log('Wrote existing_epics.json to ' + folder);
        } catch (fetchError) {
            console.error('Failed to fetch epics, continuing without file:', fetchError);
        }

        try {
            var rawStories = tracker.searchIssues(
                // JQL text: provider-specific query (WIQL on ado)
                'project = ' + project + ' AND issuetype = Story ORDER BY created DESC', {
                fields: ['key', 'summary', 'status', 'priority', 'parent']
            });
            var stories = [];
            for (var j = 0; j < rawStories.length; j++) {
                try {
                    var s = tracker.getIssue(rawStories[j].key);
                    var sf = s.fields || {};
                    stories.push({
                        key: s.key || '',
                        summary: sf.summary || '',
                        description: sf.description || '',
                        status: sf.status ? sf.status.name : '',
                        priority: sf.priority ? sf.priority.name : '',
                        diagrams: findField(sf, 'Diagrams') || null,
                        acceptanceCriteria: findField(sf, 'Acceptance Criteria') || findField(sf, 'Acceptance Criterias') || null,
                        solution: findField(sf, 'Solution') || null,
                        parent: sf.parent ? sf.parent.key : null
                    });
                } catch (e) {
                    console.error('Failed to fetch story ' + rawStories[j].key + ':', e);
                }
            }
            console.log('Found ' + stories.length + ' stories');
            file_write(folder + '/existing_stories.json', '{"stories":' + JSON.stringify(stories, null, 2) + '}');
            console.log('Wrote existing_stories.json to ' + folder);
        } catch (fetchError) {
            console.error('Failed to fetch stories, continuing without file:', fetchError);
        }
    } catch (error) {
        console.error('Error in fetchEpicsToInput:', error);
    }
}

if (typeof module !== "undefined" && module.exports) {
    module.exports = { action, findField };
}

/**
 * Intake Pre-Action
 * 1. Checks for WIP label (returns false to stop processing if found)
 * 2. Fetches existing epics and writes them into the input folder
 *    (file_write creates parent dirs, so this runs before dmtools creates input/<KEY>/)
 */

var trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        var ticket = params.ticket;
        var metadata = params.metadata;
        var ticketKey = ticket.key;
        var tracker = trackersModule.createTracker(null, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

        // --- WIP label check ---
        if (metadata && metadata.contextId) {
            var wipLabel = metadata.contextId + '_wip';
            var labels = ticket.fields && ticket.fields.labels ? ticket.fields.labels : [];

            if (labels.includes(wipLabel)) {
                console.log('Ticket ' + ticketKey + ' has WIP label "' + wipLabel + '" - skipping');
                try {
                    tracker.postComment(ticketKey, 'h3. *Processing Skipped*\n\n' +
                        'This ticket has the *' + wipLabel + '* label indicating work is in progress.\n' +
                        'Processing will be skipped until the label is removed.\n\n' +
                        '_Remove the label to allow automated processing._');
                } catch (e) {
                    console.warn('Failed to post skip comment:', e);
                }
                return false;
            }
        } else {
            console.log('No contextId in metadata, skipping WIP check');
        }

        // --- Fetch existing epics into input folder ---
        // file_write creates parent directories automatically,
        // so this works even before dmtools creates input/<KEY>/
        var inputFolder = 'input/' + ticketKey;
        var project = ticketKey.split('-')[0];
        console.log('Fetching existing epics for ' + ticketKey + '...');

        try {
            var rawEpics = tracker.searchIssues('project = ' + project + ' AND issuetype = Epic ORDER BY created DESC', {
                fields: ['key', 'summary', 'description', 'priority', 'diagrams', 'parent']
            });
            var epics = [];
            for (var i = 0; i < rawEpics.length; i++) {
                var issue = rawEpics[i];
                var f = issue.fields || {};
                epics.push({
                    key: issue.key || '',
                    summary: f.summary || '',
                    description: f.description || '',
                    priority: f.priority ? f.priority.name : '',
                    diagrams: f.diagrams || null,
                    parent: f.parent ? f.parent.key : null
                });
            }
            console.log('Found ' + epics.length + ' epics');
            file_write(inputFolder + '/existing_epics.json', '{"epics":' + JSON.stringify(epics, null, 2) + '}');
            console.log('Wrote existing_epics.json to ' + inputFolder);
        } catch (fetchError) {
            console.error('Failed to fetch epics, continuing without file:', fetchError);
        }

        try {
            var rawStories = tracker.searchIssues('project = ' + project + ' AND issuetype = Story ORDER BY created DESC', {
                fields: ['key', 'summary', 'status', 'priority', 'diagrams', 'parent']
            });
            var stories = [];
            for (var j = 0; j < rawStories.length; j++) {
                var s = rawStories[j];
                var sf = s.fields || {};
                stories.push({
                    key: s.key || '',
                    summary: sf.summary || '',
                    status: sf.status ? sf.status.name : '',
                    priority: sf.priority ? sf.priority.name : '',
                    diagrams: sf.diagrams || null,
                    parent: sf.parent ? sf.parent.key : null
                });
            }
            console.log('Found ' + stories.length + ' stories');
            file_write(inputFolder + '/existing_stories.json', '{"stories":' + JSON.stringify(stories, null, 2) + '}');
            console.log('Wrote existing_stories.json to ' + inputFolder);
        } catch (fetchError) {
            console.error('Failed to fetch stories, continuing without file:', fetchError);
        }

        return true;

    } catch (error) {
        console.error('Error in intakePreAction:', error);
        return true; // don't block on unexpected error
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action: action };
}

