#!/bin/bash
# Mirror of .github/workflows/quality.yml crap job: instrument -> run node harness with coverage -> crap4js report.
set -e
REPO=/home/runner/work/dmtools-agents/dmtools-agents
WORK=/tmp/crapwork
BIN=$WORK/tools/node_modules/.bin
TAG=${1:-current}

rm -rf "$WORK/inst" "$WORK/cov"
cd "$REPO"
"$BIN/nyc" instrument --cwd . . "$WORK/inst"
rsync -a --exclude '*.js' --exclude '.git' ./ "$WORK/inst/"
(cd "$WORK/inst" && git init -q && git add -A -f . >/dev/null 2>&1 || true)

cd "$WORK/inst"
FILES="$(node -e "console.log(require('./js/unit-tests/run_all.json').params.jobParams.testFiles.join(' '))")"
node "$REPO/ci/run_with_coverage.js" \
  "$WORK/inst/js/unit-tests/node_testRunner.js" \
  "$WORK/cov/coverage-final.json" $FILES | tail -3

"$BIN/crap4js" . --coverage "$WORK/cov/coverage-final.json" --threshold 8 > "$WORK/crap-$TAG.txt" || true
echo "--- report head ($TAG) ---"
head -5 "$WORK/crap-$TAG.txt"
echo "--- target functions ($TAG) ---"
grep -E "js/redirectToRepoAgent|js/unblockResolvedDependencies|js/fetchEpicsToInput|js/intakePreAction" "$WORK/crap-$TAG.txt" | grep -v "unit-tests" || true
echo "--- global stats ($TAG) ---"
node -e '
const fs = require("fs");
const lines = fs.readFileSync(process.argv[1], "utf8").split("\n");
let vals = [];
for (const l of lines) {
  const c = l.trim().split(/\s+/);
  if (c.length >= 5 && /\.(js|mjs|cjs)$/.test(c[1]) && !/\/(unit-tests|test)\//.test(c[1]) && !isNaN(parseFloat(c[c.length - 1]))) {
    vals.push(parseFloat(c[c.length - 1]));
  }
}
const max = vals.length ? Math.max(...vals) : 0;
const over = vals.filter((x) => x > 8).length;
console.log("product fns measured: " + vals.length + ", CRAP max: " + max + ", fns above 8: " + over);
' "$WORK/crap-$TAG.txt"

