/**
 * redirectToRepoAgent.js
 * preJSAction for story_development_redirect*.json
 *
 * Extracts [repo] from ticket summary, then runs:
 *   dmtools run "{repo}/{targetAgentName}" --inputJql "key={ticketKey}" --debug
 *
 * customParams.targetAgentName controls which agent to delegate to
 * (e.g. "story_development.json" or "story_development_test.json").
 *
 * IMPORTANT: --debug is required here. Without it, dmtools' launcher selects
 * log4j2-cli.xml (Root level OFF) for this nested process, which silently
 * discards EVERY java-side logger.info()/warn() call — including
 * CliExecutionHelper's "Executing CLI command: ..." announcement and, more
 * importantly, CommandLineUtils.runCommand()'s real-time streaming of the
 * actual CLI agent's (Copilot/etc.) own stdout via logger.info(line). Only
 * plain JS console.log() calls (which bypass log4j, writing straight to
 * System.out) would have survived — making it look like the CLI agent never
 * ran at all, when it may well have, just with zero visibility.
 *
 * Returns false to abort own processing — target agent handles everything.
 */


// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}

function action(params) {
    var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
    var folder = actualParams.inputFolderPath || '';
    var customParams = (params.jobParams && params.jobParams.customParams) || actualParams.customParams || {};
    var targetAgentName = customParams.targetAgentName || 'story_development.json';
    initTracker(null, customParams);

    var ticket = params.ticket || actualParams.ticket;
    if (!ticket || !ticket.fields) {
        var keyFromFolder = folder.split('/').pop() || '';
        try {
            ticket = getTracker().getIssue(keyFromFolder);
        } catch (e) {
            console.error('redirectToRepoAgent: could not fetch ticket: ' + e);
            return false;
        }
    }

    // ticket.key is the authoritative source — inputFolderPath may be empty when ticketContextDepth=0
    var ticketKey = (ticket && ticket.key) ? ticket.key : (folder.split('/').pop() || '');

    var summary = (ticket && ticket.fields && ticket.fields.summary)
        ? ticket.fields.summary.toString()
        : '';

    var bracketEnd = summary.indexOf(']');
    if (summary.charAt(0) !== '[' || bracketEnd === -1) {
        console.error('redirectToRepoAgent: no [repo] tag found in summary: "' + summary + '"');
        return false;
    }
    var repoName = summary.substring(1, bracketEnd).trim();
    var agentsDir = customParams.repoAgentsDir || 'repo-agents';
    var agent = agentsDir + '/' + repoName + '/' + targetAgentName;

    console.log('redirectToRepoAgent: ' + ticketKey + ' \u2192 ' + agent);

    // Forward the CI run URL so the target agent traces its run to the ticket
    var ciRunUrl = actualParams.ciRunUrl || params.ciRunUrl || (params.jobParams && params.jobParams.ciRunUrl) || '';
    var command = 'dmtools --debug run "' + agent + '" --inputJql "key=' + ticketKey + '"';
    if (ciRunUrl) {
        command += ' --ciRunUrl "' + ciRunUrl + '"';
    }

    try {
        cli_execute_command({ command: command });
    } catch (e) {
        console.error('redirectToRepoAgent: failed to run ' + agent + ': ' + e);
        return false;
    }

    return false;
}

if (typeof module !== 'undefined') {
    module.exports = { action: action };
}

/**
 * Unblock Resolved Dependencies — postJSAction for unblock_resolved_dependencies agent.
 *
 * Runs on every SM cycle for each ticket in "Blocked" status.
 * - Reads issuelinks to find all "is blocked by" dependencies (inwardIssue with Blocks link type).
 * - If all blockers are in a terminal status (Done, Merged, Passed, Closed, Irrelevant)
 *   or the blocker was deleted (inwardIssue === null), moves the ticket to Backlog.
 * - Otherwise leaves the ticket in Blocked.
 */

const configLoader = require('./configLoader.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const trackersModule = require('./common/trackers.js');

function isResolved(blocker, terminalStatuses) {
    // Deleted ticket — no inwardIssue object at all
    if (!blocker) return true;

    var statusName = blocker.fields && blocker.fields.status && blocker.fields.status.name;
    if (!statusName) return false;

    return terminalStatuses.indexOf(statusName) !== -1;
}

function action(params) {
    var ticketKey = params.ticket && params.ticket.key;
    if (!ticketKey) {
        console.error('No ticket key provided');
        return { success: false, action: 'missing_ticket' };
    }

    var projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
    var jiraConfig = projectConfig.jira;
    var tracker = trackersModule.createTracker(projectConfig, (params.jobParams && params.jobParams.customParams) || {});
    var terminalStatuses = [
        jiraConfig.statuses.DONE,
        jiraConfig.statuses.MERGED,
        jiraConfig.statuses.PASSED,
        jiraConfig.statuses.IRRELEVANT,
        // Not part of STATUSES/config — kept as a literal for backward compatibility
        'Closed'
    ].filter(Boolean);

    console.log('=== Unblock resolved dependencies check for', ticketKey, '===');

    var ticket;
    try {
        ticket = tracker.getIssue(ticketKey, ['issuelinks']);
    } catch (e) {
        console.warn('Failed to fetch ticket details:', e.message || e);
        return { success: false, action: 'fetch_failed', error: e.toString() };
    }

    var links = (ticket && ticket.fields && ticket.fields.issuelinks) || [];

    // Find all inward blockers (tickets that block the current one)
    var blockers = [];
    for (var i = 0; i < links.length; i++) {
        var link = links[i];
        // inwardIssue means: current ticket is blocked by the inwardIssue
        if (link.inwardIssue && link.type && link.type.name === 'Blocks') {
            blockers.push(link.inwardIssue);
        }
    }

    console.log('Found', blockers.length, 'blocker(s) for', ticketKey);

    // If no blockers exist, the ticket shouldn't be in Blocked status
    if (blockers.length === 0) {
        console.log('No active blockers found — moving', ticketKey, 'to Backlog');
        try {
            tracker.moveToStatus(ticketKey, jiraConfig.statuses.BACKLOG);
            tracker.postComment(ticketKey, 'h3. ✅ Auto-unblocked — No Active Blockers\n\n' +
                    'This ticket was in *Blocked* status but no active "is blocked by" dependencies were found.\n\n' +
                    'Automatically moved back to *Backlog* for re-processing.');
            console.log('✅ Moved', ticketKey, 'to Backlog (no blockers)');
            return { success: true, action: 'moved_to_backlog_no_blockers', ticketKey };
        } catch (e) {
            console.warn('Failed to move ticket to Backlog:', e.message || e);
            return { success: false, action: 'move_failed', error: e.toString() };
        }
    }

    // Check if all blockers are resolved
    var unresolved = [];
    for (var j = 0; j < blockers.length; j++) {
        var b = blockers[j];
        var bKey = b.key || '?';
        var bStatus = b.fields && b.fields.status && b.fields.status.name || 'Unknown';
        if (isResolved(b, terminalStatuses)) {
            console.log('  Blocker', bKey, 'is resolved (', bStatus, ')');
        } else {
            console.log('  Blocker', bKey, 'is NOT resolved (', bStatus, ')');
            unresolved.push({ key: bKey, status: bStatus });
        }
    }

    if (unresolved.length > 0) {
        console.log('Still blocked by', unresolved.length, 'unresolved ticket(s):', unresolved.map(function(u) { return u.key; }).join(', '));
        return { success: true, action: 'still_blocked', unresolved: unresolved, ticketKey };
    }

    // All blockers resolved → move to Backlog
    console.log('All', blockers.length, 'blocker(s) resolved — moving', ticketKey, 'to Backlog');
    try {
        tracker.moveToStatus(ticketKey, jiraConfig.statuses.BACKLOG);
    } catch (e) {
        console.warn('Failed to move ticket to Backlog:', e.message || e);
        return { success: false, action: 'move_failed', error: e.toString() };
    }

    var resolvedKeys = blockers.map(function(b) {
        return b.key + ' (' + (b.fields && b.fields.status && b.fields.status.name || '?') + ')';
    }).join(', ');

    try {
        tracker.postComment(ticketKey, 'h3. ✅ Auto-unblocked — All Dependencies Resolved\n\n' +
                'All *' + blockers.length + '* blocker(s) are now in a terminal status:\n' +
                resolvedKeys.split(', ').map(function(k) { return '- ' + k; }).join('\n') + '\n\n' +
                'Automatically moved back to *Backlog* for re-processing.');
        console.log('✅ Posted unblock comment to Jira');
    } catch (e) {
        console.warn('Failed to post comment:', e.message || e);
    }

    console.log('✅ Moved', ticketKey, 'to Backlog');

    // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
    // wrote outputs/*_usage.json during the agent run.
    try {
        tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
    } catch (e) {
        console.warn('Failed to post token usage comments:', e);
    }

    return { success: true, action: 'moved_to_backlog', blockersResolved: blockers.length, ticketKey };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Fetch Epics To Input Pre-CLI Action
 * Fetches existing epics and writes them to the input folder before CLI agent runs.
 * Receives params.inputFolderPath from DMTools after input folder creation.
 */

/**
 * Pre-CLI action: fetch existing epics into input folder
 *
 * @param {Object} params - Parameters from DMTools
 * @param {string} params.inputFolderPath - Path to the input folder for this run
 */

// Load-time require (gh-823): a deferred require would resolve against the
// pack js/ root only — hoist every require to the top of the module.
var trackersModule = require("./common/trackers.js");

/**
 * Find a field value by partial key name (handles "Display Name (customfieldXXX)" keys).
 */
function findField(fields, nameSubstring) {
    for (var key in fields) {
        if (key.indexOf(nameSubstring) !== -1) {
            return fields[key];
        }
    }
    return null;
}

function action(params) {
    try {
        const folder = params.inputFolderPath;
        var ticketKey = folder ? folder.split('/').pop() : '';
        var project = ticketKey ? ticketKey.split('-')[0] : '';
        var tracker = trackersModule.createTracker(null, (params.jobParams && params.jobParams.customParams) || params.customParams || {});
        console.log('Fetching existing epics for project ' + project + '...');

        try {
            var rawEpics = tracker.searchIssues(
                // JQL text: provider-specific query (WIQL on ado)
                'project = ' + project + ' AND issuetype = Epic ORDER BY created DESC', {
                fields: ['key', 'summary', 'description', 'priority', 'parent']
            });
            var epics = [];
            for (var i = 0; i < rawEpics.length; i++) {
                try {
                    var issue = tracker.getIssue(rawEpics[i].key);
                    var f = issue.fields || {};
                    epics.push({
                        key: issue.key || '',
                        summary: f.summary || '',
                        description: f.description || '',
                        priority: f.priority ? f.priority.name : '',
                        diagrams: f['Diagrams (customfield_10296)'] || f.Diagrams || null,
                        parent: f.parent ? f.parent.key : null
                    });
                } catch (e) {
                    console.error('Failed to fetch epic ' + rawEpics[i].key + ':', e);
                }
            }
            console.log('Found ' + epics.length + ' epics');
            file_write(folder + '/existing_epics.json', '{"epics":' + JSON.stringify(epics, null, 2) + '}');
            console.log('Wrote existing_epics.json to ' + folder);
        } catch (fetchError) {
            console.error('Failed to fetch epics, continuing without file:', fetchError);
        }

        try {
            var rawStories = tracker.searchIssues(
                // JQL text: provider-specific query (WIQL on ado)
                'project = ' + project + ' AND issuetype = Story ORDER BY created DESC', {
                fields: ['key', 'summary', 'status', 'priority', 'parent']
            });
            var stories = [];
            for (var j = 0; j < rawStories.length; j++) {
                try {
                    var s = tracker.getIssue(rawStories[j].key);
                    var sf = s.fields || {};
                    stories.push({
                        key: s.key || '',
                        summary: sf.summary || '',
                        description: sf.description || '',
                        status: sf.status ? sf.status.name : '',
                        priority: sf.priority ? sf.priority.name : '',
                        diagrams: findField(sf, 'Diagrams') || null,
                        acceptanceCriteria: findField(sf, 'Acceptance Criteria') || findField(sf, 'Acceptance Criterias') || null,
                        solution: findField(sf, 'Solution') || null,
                        parent: sf.parent ? sf.parent.key : null
                    });
                } catch (e) {
                    console.error('Failed to fetch story ' + rawStories[j].key + ':', e);
                }
            }
            console.log('Found ' + stories.length + ' stories');
            file_write(folder + '/existing_stories.json', '{"stories":' + JSON.stringify(stories, null, 2) + '}');
            console.log('Wrote existing_stories.json to ' + folder);
        } catch (fetchError) {
            console.error('Failed to fetch stories, continuing without file:', fetchError);
        }
    } catch (error) {
        console.error('Error in fetchEpicsToInput:', error);
    }
}

if (typeof module !== "undefined" && module.exports) {
    module.exports = { action, findField };
}

/**
 * Intake Pre-Action
 * 1. Checks for WIP label (returns false to stop processing if found)
 * 2. Fetches existing epics and writes them into the input folder
 *    (file_write creates parent dirs, so this runs before dmtools creates input/<KEY>/)
 */

var trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        var ticket = params.ticket;
        var metadata = params.metadata;
        var ticketKey = ticket.key;
        var tracker = trackersModule.createTracker(null, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

        // --- WIP label check ---
        if (metadata && metadata.contextId) {
            var wipLabel = metadata.contextId + '_wip';
            var labels = ticket.fields && ticket.fields.labels ? ticket.fields.labels : [];

            if (labels.includes(wipLabel)) {
                console.log('Ticket ' + ticketKey + ' has WIP label "' + wipLabel + '" - skipping');
                try {
                    tracker.postComment(ticketKey, 'h3. *Processing Skipped*\n\n' +
                        'This ticket has the *' + wipLabel + '* label indicating work is in progress.\n' +
                        'Processing will be skipped until the label is removed.\n\n' +
                        '_Remove the label to allow automated processing._');
                } catch (e) {
                    console.warn('Failed to post skip comment:', e);
                }
                return false;
            }
        } else {
            console.log('No contextId in metadata, skipping WIP check');
        }

        // --- Fetch existing epics into input folder ---
        // file_write creates parent directories automatically,
        // so this works even before dmtools creates input/<KEY>/
        var inputFolder = 'input/' + ticketKey;
        var project = ticketKey.split('-')[0];
        console.log('Fetching existing epics for ' + ticketKey + '...');

        try {
            var rawEpics = tracker.searchIssues('project = ' + project + ' AND issuetype = Epic ORDER BY created DESC', {
                fields: ['key', 'summary', 'description', 'priority', 'diagrams', 'parent']
            });
            var epics = [];
            for (var i = 0; i < rawEpics.length; i++) {
                var issue = rawEpics[i];
                var f = issue.fields || {};
                epics.push({
                    key: issue.key || '',
                    summary: f.summary || '',
                    description: f.description || '',
                    priority: f.priority ? f.priority.name : '',
                    diagrams: f.diagrams || null,
                    parent: f.parent ? f.parent.key : null
                });
            }
            console.log('Found ' + epics.length + ' epics');
            file_write(inputFolder + '/existing_epics.json', '{"epics":' + JSON.stringify(epics, null, 2) + '}');
            console.log('Wrote existing_epics.json to ' + inputFolder);
        } catch (fetchError) {
            console.error('Failed to fetch epics, continuing without file:', fetchError);
        }

        try {
            var rawStories = tracker.searchIssues('project = ' + project + ' AND issuetype = Story ORDER BY created DESC', {
                fields: ['key', 'summary', 'status', 'priority', 'diagrams', 'parent']
            });
            var stories = [];
            for (var j = 0; j < rawStories.length; j++) {
                var s = rawStories[j];
                var sf = s.fields || {};
                stories.push({
                    key: s.key || '',
                    summary: sf.summary || '',
                    status: sf.status ? sf.status.name : '',
                    priority: sf.priority ? sf.priority.name : '',
                    diagrams: sf.diagrams || null,
                    parent: sf.parent ? sf.parent.key : null
                });
            }
            console.log('Found ' + stories.length + ' stories');
            file_write(inputFolder + '/existing_stories.json', '{"stories":' + JSON.stringify(stories, null, 2) + '}');
            console.log('Wrote existing_stories.json to ' + inputFolder);
        } catch (fetchError) {
            console.error('Failed to fetch stories, continuing without file:', fetchError);
        }

        return true;

    } catch (error) {
        console.error('Error in intakePreAction:', error);
        return true; // don't block on unexpected error
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action: action };
}

