    var p = args && args.path ? args.path : args;
    var dir = resolveExisting(p, function(st) { return st.isDirectory(); });
    if (!dir) return null;
    return JSON.stringify({ entries: fs.readdirSync(dir).map(function(n) { return path.join(dir, n); }).sort() });
