                diagrams: null,
                parent: null
            }
        ]);

        assert.equal(loaded.calls.writes[1].path, 'input/PROJ-5/existing_stories.json');
        var storiesDoc = JSON.parse(loaded.calls.writes[1].content);
        assert.deepEqual(storiesDoc.stories, [
            {
                key: 'PROJ-20',
                summary: 'Story one',
                status: 'To Do',
                priority: 'Low',
                diagrams: 'diag-2',
