        assert.equal(result.blockersResolved, 3);
        assert.equal(result.ticketKey, 'PROJ-2');
        assert.deepEqual(loaded.calls.statusMoves, [{ key: 'PROJ-2', statusName: 'Backlog' }]);
        assert.equal(loaded.calls.comments.length, 1);
