            searchResults: (function () {
                var m = {};
                m[EPIC_JQL] = { results: [{ key: 'PROJ-10' }, { key: 'PROJ-11' }] };
                m[STORY_JQL] = { results: [{ key: 'PROJ-20' }, { key: 'PROJ-21' }] };
                return m;
            })(),
            getIssue: (function () {
                var m = {};
                m['PROJ-10'] = {
                    key: 'PROJ-10',
                    fields: {
                        summary: 'Epic one',
                        description: 'Desc one',
                        priority: { name: 'High' },
                        'Diagrams (customfield_10296)': 'diag-url-1',
                        parent: { key: 'PROJ-1' }
                    }
                };
                m['PROJ-11'] = {
                    key: 'PROJ-11',
                    fields: {
                        summary: 'Epic two',
                        Diagrams: 'fallback-diag'
