        plain.mod.action({
            ticket: { key: 'PROJ-6', fields: { summary: '[a] b' } }
        });
        assert.deepEqual(plain.calls.cli, [
            { command: 'dmtools --debug run "repo-agents/a/story_development.json" --inputJql "key=PROJ-6"' }
        ]);
