        assert.equal(loaded.calls.writes[1].path, 'input/PROJ-3/existing_stories.json');
        var storiesDoc = JSON.parse(loaded.calls.writes[1].content);
        assert.ok(storiesDoc.stories.length === 2, 'both stories written');
