            if (spec && spec.throwOnSearch) throw new Error('search down: ' + jql);
            return (spec && spec.results) || [];
        },
        postComment: function (key, body) {
            calls.comments.push({ key: key, body: body });
            if (opts.commentThrows) throw new Error('comment down');
            return null;
        }
