        assert.equal(result, true, 'processing continues after the pre-action');
        assert.deepEqual(loaded.calls.search, [
            {
                jql: EPIC_JQL,
                opts: { fields: ['key', 'summary', 'description', 'priority', 'diagrams', 'parent'] }
            },
            {
