        var issues = collectMappedIssues(tracker, spec);
        console.log('Found ' + issues.length + ' ' + spec.plural);
        file_write(folder + '/' + spec.fileName, '{"' + spec.listKey + '":' + JSON.stringify(issues, null, 2) + '}');
