    for (var i = 0; i < rawIssues.length; i++) {
        try {
            issues.push(spec.map(tracker.getIssue(rawIssues[i].key)));
        } catch (e) {
            console.error(spec.brokenLabel + ' ' + rawIssues[i].key + ':', e);
